// accountsUsage displays the usage of the accounts command and its subcommands.
func accountsUsage() {
	fmt.Fprintln(os.Stderr, `Social media account CRUD service`)
	fmt.Fprintf(os.Stderr, "Usage:\n    %s [globalflags] accounts COMMAND [flags]\n\n", os.Args[0])
	fmt.Fprintln(os.Stderr, "COMMAND:")
	fmt.Fprintln(os.Stderr, `    list: List all accounts; never returns cookies`)
	fmt.Fprintln(os.Stderr, `    get: Get an account by ID with linked subjects; never returns cookies`)
	fmt.Fprintln(os.Stderr, `    create: Create a new account`)
	fmt.Fprintln(os.Stderr, `    update-cookies: Update cookies for an account; encrypts with AES-256-GCM`)
	fmt.Fprintln(os.Stderr, `    delete: Delete an account and all subject_accounts links`)
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "Additional help:")
	fmt.Fprintf(os.Stderr, "    %s accounts COMMAND --help\n", os.Args[0])
}
